/* ---------- typed model ---------- */
type Bag = Record<string, unknown>;
type Dict = Record<string, string>;
export type PaAmend = { at: string; by: string; reason: string; prev: Bag };
export type PaHist = { d: string; t: string };
/** One clinical entry; the kinds (history, allergies, problems, medication, encounters, observations, labs, imaging, assessments, plans, therapy episodes) share provenance fields. */
export type PaEntry = {
  id: string; verif: string; src: string; srcDoc?: string | null; by: string; byPr?: string | null; at: string; amend: PaAmend[]; status: string; mergedFrom?: string;
  text?: string; cat?: string; substance?: string; reaction?: string; severity?: string; name?: string; dose?: string; route?: string; freq?: string; start?: string; end?: string;
  date?: string; type?: string; note?: string; addenda?: { id: string; text: string; reason: string; by: string; at: string }[]; signedBy?: string; signedAt?: string; appt?: string; pr?: string;
  code?: string; v?: number | string; v2?: number | string; ts?: string; unit?: string; test?: string; result?: string; ref?: string; flag?: string; modality?: string; site?: string; concl?: string;
  title?: string; tool?: string; score?: string; summary?: string; spec?: string; goals?: PaGoal[]; measures?: PaMeasure[]; notes?: { id: string; d: string; text: string; by: string; at: string }[];
  initial?: { text: string; d: string; by: string } | null; discharge?: { text: string; d: string; by: string } | null; reason?: string;
  onset?: string; region?: string; review?: string; crit?: string; kind?: string; state?: string; problems?: string[]; formRef?: string | null; interventions?: string; method?: string; lab?: string; label?: string; [k: string]: unknown;
};
