export type PaMeasure = { id: string; name: string; unit: string; note: string; formRef: string | null; pts: { d: string; v: number; by: string }[] };
export type PaClin = { hist: PaEntry[]; allergyState: { state: string; by?: string; at?: string; mergedFrom?: string }; allergies: PaEntry[]; problems: PaEntry[]; meds: PaEntry[]; enc: PaEntry[]; obs: PaEntry[]; labs: PaEntry[]; imaging: PaEntry[]; assess: PaEntry[]; plans: PaEntry[]; therapy: PaEntry[] };
export type PaRel = { id: string; type: string; ref: string | null; name: string; phone: string; email: string; from: string; to: string; verif: string; doc: string | null; scope: string[]; emergency: boolean; note: string; by: string; at: string; hist?: { at: string; by: string; snap: string }[]; mergedFrom?: string };
export type PaConsentT = { id: string; type: string; state: string; date: string; by: string; scope: string; doc: string | null; expires: string; recBy: string; at: string; note: string; hist: { state: string; date: string; [k: string]: unknown }[]; mergedFrom?: string };
export type PaDocT = { id: string; cat: string; title: string; name: string; mime: string; size: number; file: string | null; d: string; by: string; at: string; conf: string; status: string; derivOf: string | null; deriv: string | null; vers: { n: number; name: string; size: number; file: string | null; mime: string; at: string; by: string }[]; src: string; note: string; metaHist?: Bag[]; archived?: { at: string; by: string; reason: string }; mergedFrom?: string };
