/* ===== v64 · Patients & Dossiers médicaux — domain model and services (no UI here) =====
   Stable identifiers, explicit states, provenance + verification on every clinical entry, amendments instead of overwrites,
   care-team scoped clinical access with logged emergency access, consent records, duplicate scoring that never relies
   on name similarity or family links alone, merge with full audit trail. All data is synthetic. */
const PA_KEY="remotion-patients";
const PA: PaApp={st:null,ui:{view:"list",arg:null,sec:"over",stack:[],flt:{},sort:"name",dir:1,page:0,size:25,q:"",open:{},bg:{},drawer:null,tl:{}}};
class PaErr extends Error{k: string;x: unknown;constructor(k: string,x?: unknown){super(k);this.k=k;this.x=x}}
const paIso=(d: string | number | Date)=>{const z=new Date(d);return z.getFullYear()+"-"+String(z.getMonth()+1).padStart(2,"0")+"-"+String(z.getDate()).padStart(2,"0")};
const paToday=()=>PA.today||orgToday();/* v93 */
/** v93: the archive confirmation says what stays linked; filled by apps/health/datalinks (no import cycle) */
let sdArchiveNoteHook: (pid: string) => string = () => "";
export function paSetArchiveNote(fn: (pid: string) => string) { sdArchiveNoteHook = fn; }
const paAdd=(iso: string,n: number)=>{const d=new Date(iso+"T12:00:00");d.setDate(d.getDate()+n);return paIso(d)};
const paAge=(birth: string | null | undefined,at?: string)=>{if(!birth)return null;const b=new Date(birth+"T12:00:00"),t=new Date((at||paToday())+"T12:00:00");let a=t.getFullYear()-b.getFullYear();if(t.getMonth()<b.getMonth()||(t.getMonth()===b.getMonth()&&t.getDate()<b.getDate()))a--;return a};
const paNorm=(s: unknown)=>String(s||"").toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g,"").replace(/[^a-z0-9@.+ ]/g," ").replace(/\s+/g," ").trim();
const paDigits=(s: unknown)=>String(s||"").replace(/\D/g,"");
const paId=(p: string)=>p+Date.now().toString(36)+Math.random().toString(36).slice(2,6);

