const PA_OBS: Record<string, [string, string]>={height:["Taille|Height|Größe|الطول","cm"],weight:["Poids|Weight|Gewicht|الوزن","kg"],bp:["Pression artérielle|Blood pressure|Blutdruck|ضغط الدم","mmHg"],hr:["Fréquence cardiaque|Heart rate|Herzfrequenz|معدل النبض","/min"],temp:["Température|Temperature|Temperatur|الحرارة","°C"],spo2:["SpO₂|SpO₂|SpO₂|SpO₂","%"],pain:["Douleur déclarée (0–10, échelle de l’équipe)|Reported pain (0–10, team scale)|Schmerz angegeben (0–10)|الألم المصرح به (0–10)","/10"]};
