  const EST=["s1","s1","s2","s1","s1","s2","s2","s1","s2","s1","s1","s2","s1","s2"],STREETS=["12 rue des Lilas","4 avenue de la République","18 rue Oberkampf","7 boulevard Voltaire","22 rue de Montreuil","3 place Fictive","9 impasse des Tests"];
  const mk=(i: number): PaPat=>{const seq=++S.seq;const mrn="PAT-"+String(seq).padStart(6,"0");const em=paNorm(FN[i]).replace(/ /g,"")+"."+paNorm(LN[i]).replace(/ /g,"")+"@exemple.invalid";
    return {id:"pa"+(i+1),mrn,ids:[{sys:"local",v:mrn,since:A(-400+i*9)}],status:"active",first:FN[i],last:LN[i],birthName:"",birth:BIRTH[i],sex:SEX[i],gender:"",lang:"fr",
     contact:{phone:"06 00 00 "+String(10+i).padStart(2,"0")+" 00",phone2:"",email:em,addr:{l1:STREETS[i%STREETS.length],zip:i%3?"75011":"93100",city:i%3?"Paris":"Montreuil",country:"France"},pref:i%2?"sms":"email",noVoicemail:false},
     admin:{est:EST[i],payer:"c"+(i+1),insurer:"Organisme d’assurance fictif",memberNo:"",gp:i%4?"":"Dr Paul Exemple (déclaré)",referrer:""},prefs:{lang:"fr",interp:false,access:"",comm:"",notes:""},
     rel:[],team:[],consents:[],notices:[],docs:[],clin:paClinBlank(),hist:[{d:A(-400+i*9),t:"Dossier créé|Record created|Akte angelegt|أنشئ الملف"}],created:now,upd:now,ver:1,createdBy:"Accueil (démo)",synthetic:true}};
  for(let i=0;i<14;i++)S.pats.push(mk(i));
