function paFormDone(pid: string,formId: string){paNeed("pat.edit");const p=paGet(pid);const f=(p.forms||[]).find(x=>x.id===formId&&x.status==="todo");if(!f)throw new PaErr("pa_eNotFound");f.status="done";f.doneAt=new Date().toISOString();f.doneBy=paUser();paTouch(p);paLog("form.link",pid,formId+" → done");return f}
