const PA_CHAN: Dict={phone:"Téléphone|Phone|Telefon|الهاتف",sms:"SMS|SMS|SMS|رسائل قصيرة",email:"E-mail|E-mail|E-Mail|البريد",mail:"Courrier|Post|Post|البريد الورقي"};
function paAllergyLine(p: PaPat){const st=p.clin.allergyState?.state||"unknown";const act=p.clin.allergies.filter(a=>a.status==="active");
  if(act.length)return `<div class="pa-alg bad" role="note">${hri("alertTri",15)}<span><b>${hrE(L4("Allergies / intolérances|Allergies / intolerances|Allergien / Unverträglichkeiten|الحساسية / عدم التحمل"))} :</b> ${act.map(a=>`${hrE(a.substance)}${a.verif!=="confirmed"?` <small>(${hrE(L4(PA_VERIF[a.verif]))})</small>`:""}`).join(", ")}</span></div>`;
  if(st==="nka")return `<div class="pa-alg ok" role="note">${hri("check",15)}<span>${hrE(L4("Aucune allergie connue — déclaré par|No known allergies — stated by|Keine bekannten Allergien — angegeben von|لا حساسية معروفة — صرح بها"))} ${hrE(p.clin.allergyState.by||"—")} (${hrE(paDate(String(p.clin.allergyState.at||"").slice(0,10)))})</span></div>`;
  return `<div class="pa-alg unk" role="note">${hri("alert",15)}<span>${hrE(L4("Statut allergique non documenté : l’absence d’information ne signifie pas l’absence d’allergie.|Allergy status not documented: missing information does not mean no allergy.|Allergiestatus nicht dokumentiert: fehlende Angaben bedeuten nicht keine Allergie.|حالة الحساسية غير موثقة: غياب المعلومات لا يعني غياب الحساسية."))}</span></div>`}

