const PA_SEC: Record<string, PaSecDef>={};const paSec=(id: string,o: Omit<PaSecDef, "id">)=>{PA_SEC[id]=Object.assign({id},o)};
const PA_SECG=[["fiche","Fiche patient|Patient file|Patientenakte|ملف المريض"],["dm","Dossier médical|Medical record|Krankenakte|الملف الطبي"]];
paDef("record","pat",{n:"Dossier patient|Patient record|Patientenakte|ملف المريض",ic:"user",hidden:true,perm:"dir.view",page:pid=>{const p=paGet(pid);const sec=PA_SEC[PA.ui.sec]?PA.ui.sec:"over";const S=PA_SEC[sec];
  const ok=paClinOk(p);const c=paCompleteness(p);const lead=paLead(p);const bg=PA.ui.bg[p.id];
  const nav=PA_SECG.map(([g,gn])=>`<div class="pa-secg"><span>${hrE(L4(gn))}</span>${Object.values(PA_SEC).filter(s=>s.g===g).map(s=>{const lock=s.clin&&!ok;const b=!lock&&s.badge?s.badge(p):"";return `<button type="button" role="tab" class="pa-sn${lock?" lock":""}" data-pasec="${s.id}" aria-selected="${s.id===sec}" tabindex="${s.id===sec?0:-1}">${hri(lock?"lock":s.ic,14)}<span>${hrE(L4(s.n))}</span>${b?`<em>${hrE(String(b))}</em>`:""}</button>`}).join("")}</div>`).join("");
  let inner;if(S.clin&&!ok)inner=paLockedHTML(p);else{try{inner=S.html(p)}catch(e){if(!(e instanceof PaErr))console.error(e);inner=paEmpty("alert",paErr(e))}}
  return `<div class="pa-rec">${p.status==="archived"?`<div class="hr-banner warn">${hri("archive",16)}<span>${hrE(L4("Dossier archivé le|Record archived on|Archiviert am|أرشف في"))} ${hrE(paDate(String(p.archived?.at||"").slice(0,10)))} — ${hrE(p.archived?.reason||"")}</span>${paCan("archive")?`<button type="button" class="hr-btn sm" data-parestore="${p.id}">${hri("refresh",14)}${hrE(L4("Restaurer|Restore|Wiederherstellen|استعادة"))}</button>`:""}</div>`:""}
   ${bg?`<div class="hr-banner err pa-bg">${hri("key",16)}<span><b>${hrE(L4("Accès exceptionnel en cours|Emergency access in progress|Notfallzugriff aktiv|وصول استثنائي جارٍ"))}</b> — ${hrE(bg.reason)} · ${hrE(L4("tracé dans le journal d’audit|recorded in the audit log|protokolliert|مسجل في السجل"))}</span><button type="button" class="hr-btn sm" data-pabgend="${p.id}">${hrE(L4("Terminer l’accès|End access|Zugriff beenden|إنهاء الوصول"))}</button></div>`:""}
   <header class="hr-card pa-head"><div class="pa-hid">${paAvatar(p,64)}<div><h1>${hrE(paName(p))}${p.birthName?` <small>${hrE(L4("née / né|born|geb.|المولود"))} ${hrE(p.birthName)}</small>`:""}</h1>
     <p class="pa-facts"><span class="hr-mono">${hrE(p.mrn)}</span><span>${hrE(paDate(p.birth))} · ${hrE(paAgeTxt(p))}</span><span>${hrE(L4(PA_SEX[p.sex]||PA_SEX.U))}</span>${paStBadge(p.status)}${lead?`<span>${hri("stetho",12)} ${hrE(rmPracName(lead.pr))}</span>`:""}<span>${hri("building",12)} ${hrE(rmEstName(p.admin.est))}</span></p>
     ${ok?paAllergyLine(p):`<p class="pa-locked sm">${hri("lock",13)}${hrE(L4("Données cliniques masquées pour votre rôle ou hors équipe de soins.|Clinical data hidden for your role or outside the care team.|Klinische Daten verborgen.|البيانات السريرية مخفية."))}</p>`}</div></div>
    <div class="pa-hside"><button type="button" class="pa-ring" data-pasec="over" style="--p:${c.pct}" title="${hrE(L4("Complétude administrative|Administrative completeness|Vollständigkeit|الاكتمال الإداري"))}"><b>${c.pct}%</b><small>${hrE(L4("complet|complete|vollständig|مكتمل"))}</small></button>
     <div class="pa-hacts">${paCan("pat.edit")&&p.status!=="merged"?`<button type="button" class="hr-btn" data-paedit="identity|${p.id}">${hri("pen",15)}${hrE(paW("edit"))}</button>`:""}${PA_HOOKS.headActions.map(f=>f(p)).join("")}<button type="button" class="hr-ib bd" data-parm="${p.id}" aria-haspopup="menu" aria-label="${hrE(L4("Plus d’actions|More actions|Weitere Aktionen|مزيد"))}">${hri("more",16)}</button></div></div></header>
   <div class="pa-body"><nav class="pa-secn" role="tablist" aria-label="${hrE(L4("Sections du dossier|Record sections|Aktenabschnitte|أقسام الملف"))}" aria-orientation="vertical">${nav}</nav>
    <section class="pa-secb" role="tabpanel" aria-label="${hrE(L4(S.n))}" data-sec="${sec}"><div class="pa-sech"><h2>${hri(S.ic,17)}${hrE(L4(S.n))}</h2>${S.clin&&ok&&S.add&&paCan("clin.edit")?`<button type="button" class="hr-btn sm pri" data-paadd="${sec}">${hri("plus",14)}${hrE(L4(S.addN||PAW.add))}</button>`:""}${!S.clin&&S.tools?S.tools(p):""}</div>${inner}</section></div></div>`}});
const PA_HOOKS: { headActions: ((p: PaPat) => string)[]; services: ((p: PaPat) => string)[]; over: ((p: PaPat) => string)[]; encAppt?: (e: Partial<PaEntry>) => string }={headActions:[],services:[],over:[]};
function paLockedHTML(p: PaPat){const can=paCan("clin.view");return `<div class="hr-state pa-lockst"><span class="ic">${hri("lock",26)}</span><h3>${hrE(can?L4("Vous ne faites pas partie de l’équipe de soins|You are not in the care team|Nicht im Behandlungsteam|لست ضمن فريق الرعاية"):L4("Accès non autorisé pour votre rôle|Not authorised for your role|Für Ihre Rolle nicht erlaubt|غير مصرح لدورك"))}</h3><p>${hrE(can?L4("En cas de nécessité pour la prise en charge, un accès exceptionnel peut être ouvert. Il est tracé avec son motif et limité à cette session.|If needed for care, emergency access can be opened. It is recorded with its reason and limited to this session.|Bei Bedarf Notfallzugriff möglich (protokolliert).|يمكن فتح وصول استثنائي مسجل."):L4("Les données cliniques sont réservées aux professionnels de santé de l’équipe de soins.|Clinical data is reserved to the care team.|Nur für das Behandlungsteam.|البيانات مخصصة لفريق الرعاية."))}</p>${can?`<button type="button" class="hr-btn danger" data-pabg="${p.id}">${hri("key",15)}${hrE(L4("Accès exceptionnel…|Emergency access…|Notfallzugriff…|وصول استثنائي…"))}</button>`:""}</div>`}
const paCard=(ic: string,title: string,body: string,o: { cls?: string; act?: string }={})=>`<section class="hr-card pa-card${o.cls?" "+o.cls:""}"><div class="hr-ch"><h3>${hri(ic,16)}${hrE(title)}</h3>${o.act||""}</div>${body}</section>`;
const paDL=(rows: (PaDLRow | false | null | undefined | "")[])=>`<dl class="hr-dl two">${(rows.filter(Boolean) as PaDLRow[]).map(([l,v,raw])=>`<div><dt>${hrE(L4(l))}</dt><dd>${raw?v:hrE(v||"—")}</dd></div>`).join("")}</dl>`;
const paEditBtn=(sec: string,pid: string,perm?: string)=>paCan(perm||"pat.edit")&&paFind(pid)?.status!=="merged"?`<button type="button" class="hr-btn sm" data-paedit="${sec}|${pid}">${hri("pen",14)}${hrE(paW("edit"))}</button>`:"";

