paSec("allergies",{g:"dm",clin:true,n:"Allergies & intolérances|Allergies & intolerances|Allergien & Unverträglichkeiten|الحساسية وعدم التحمل",ic:"alertTri",add:1,addN:"Ajouter une allergie|Add allergy|Allergie hinzufügen|إضافة حساسية",badge:p=>p.clin.allergies.filter(e=>e.status==="active").length||(p.clin.allergyState.state==="unknown"?"?":""),html:p=>{const st=p.clin.allergyState.state;const act=p.clin.allergies.some(a=>a.status==="active");
  return `${paAllergyLine(p)}<div class="pa-row">${paCan("clin.edit")&&!act&&st!=="nka"?`<button type="button" class="hr-btn sm" data-panka="${p.id}">${hri("check",14)}${hrE(L4("Enregistrer « aucune allergie connue »|Record “no known allergy”|„Keine bekannten Allergien“ erfassen|تسجيل لا حساسية معروفة"))}</button>`:""}${paCan("clin.edit")&&st==="nka"?`<button type="button" class="hr-btn sm" data-paalgunk="${p.id}">${hrE(L4("Revenir à « non documenté »|Back to “not documented”|Zurück zu „nicht dokumentiert“|العودة إلى غير موثق"))}</button>`:""}${paErrToggle()}</div>
   ${paEntryTable("allergies",p.clin.allergies,[["Substance / agent|Substance / agent|Stoff|المادة",e=>hrE(e.substance)],["Type|Type|Typ|النوع",e=>hrE(e.type==="intolerance"?L4("Intolérance|Intolerance|Unverträglichkeit|عدم تحمل"):L4("Allergie|Allergy|Allergie|حساسية"))],["Réaction (telle que rapportée)|Reaction (as reported)|Reaktion (berichtet)|التفاعل",e=>hrE(e.reaction||"—")],["Criticité (évaluée par le soignant)|Criticality (clinician-assessed)|Kritikalität|الخطورة",e=>hrE(L4({low:"Faible|Low|Niedrig|منخفضة",high:"Élevée|High|Hoch|مرتفعة",unable:"Non évaluable|Unable to assess|Nicht beurteilbar|غير قابلة للتقييم"}[e.crit!]||"—"))],["Début|Onset|Beginn|البداية",e=>hrE(e.onset?paDate(e.onset):"—")],["Statut|Status|Status|الحالة",e=>paStChip(e.status)]])}`}});
paSec("problems",{g:"dm",clin:true,n:"Problèmes & diagnostics|Problems & diagnoses|Probleme & Diagnosen|المشكلات والتشخيصات",ic:"clip",add:1,addN:"Ajouter un problème|Add problem|Problem hinzufügen|إضافة مشكلة",badge:p=>p.clin.problems.filter(e=>e.status==="active").length||"",html:p=>`<div class="pa-row">${paErrToggle()}<span class="hr-mut sm">${hrE(L4("Les libellés sont saisis par les soignants ; aucun code ni diagnostic n’est proposé automatiquement.|Labels are entered by clinicians; no code or diagnosis is suggested automatically.|Keine automatischen Diagnosen.|لا تشخيص تلقائي."))}</span></div>${paEntryTable("problems",p.clin.problems,[["Libellé|Label|Bezeichnung|التسمية",e=>hrE(e.text)],["Nature|Kind|Art|النوع",e=>hrE(L4({diagnosis:"Diagnostic|Diagnosis|Diagnose|تشخيص",problem:"Problème|Problem|Problem|مشكلة",symptom:"Symptôme|Symptom|Symptom|عرض"}[e.kind!]||"—"))],["Début|Onset|Beginn|البداية",e=>hrE(e.onset?paDate(e.onset):"—")],["Fin|Resolved|Ende|النهاية",e=>hrE(e.end?paDate(e.end):"—")],["Statut|Status|Status|الحالة",e=>paStChip(e.status)]])}`});
