paSec("therapy",{g:"dm",clin:true,n:"Rééducation & thérapies|Therapy records|Therapien|سجلات العلاج",ic:"target",add:1,addN:"Ouvrir un épisode|Open an episode|Episode eröffnen|فتح حلقة",badge:p=>p.clin.therapy.filter(t=>t.status==="active").length||"",html:p=>{const v=paVis(p.clin.therapy).slice().sort((a,b)=>(a.status==="active"?0:1)-(b.status==="active"?0:1)||(a.start!<b.start!?1:-1));const forms=paForms();
  return `${v.length?`<div class="pa-ths">${v.map(t=>{const sf=(paSt().set.specForms||{})[t.spec!];const f=sf&&forms.find(x=>x.id===sf);const ed=paCan("clin.edit")&&t.status==="active";return `<article class="hr-card pa-th ${t.status}" data-entry="${t.id}" tabindex="-1"><header><span class="pa-thi" style="--c:${rmPrac(t.pr)?.color||"#2563eb"}">${hri("target",16)}</span><div><h3>${hrE(rmSpecName(t.spec))}${t.reason?` — <span>${hrE(t.reason)}</span>`:""}</h3><small>${hrE(rmPracName(t.pr))} · ${hrE(paDate(t.start))} → ${t.end?hrE(paDate(t.end)):hrE(L4("en cours|ongoing|laufend|جارٍ"))}</small></div><span class="pa-es ${t.status==="active"?"active":"completed"}">${hrE(t.status==="active"?L4("Épisode actif|Active episode|Aktive Episode|حلقة نشطة"):t.status==="error"?L4(PA_ESTATE.error):L4("Clôturé|Closed|Abgeschlossen|مغلقة"))}</span>${paEM("therapy",t)}</header>
   <div class="pa-thg"><section><h4>${hrE(L4("Évaluation initiale|Initial assessment|Erstbefund|التقييم الأولي"))}</h4>${t.initial?`<p>${hrE(t.initial.text)}</p><small class="hr-mut">${hrE(paDate(t.initial.d))} · ${hrE(t.initial.by)}</small>`:ed?`<button type="button" class="hr-btn sm" data-pathx="initial|${p.id}|${t.id}">${hri("plus",14)}${hrE(L4("Rédiger l’évaluation initiale|Write initial assessment|Erstbefund schreiben|كتابة التقييم الأولي"))}</button>`:`<p class="hr-mut">—</p>`}${f?`<p class="pa-line"><button type="button" class="hr-lnk" data-paform="${f.id}">${hri("clip",12)} ${hrE(f.name)}</button><small>${hrE(L4("formulaire de la spécialité (Formulaires & Enquêtes)|specialty form (Forms & Surveys)|Fachformular|نموذج التخصص"))}</small></p>`:""}</section>
    <section><h4>${hrE(L4("Objectifs|Goals|Ziele|الأهداف"))} <em class="hr-cnt">${t.goals!.length}</em></h4><ul class="pa-goals">${t.goals!.map(g=>`<li><span class="pa-gs ${g.status}">${hrE(L4(PA_GOAL[g.status]))}</span><span>${hrE(g.text)}${g.target?`<small>${hrE(L4("échéance|target|Ziel|الموعد"))} ${hrE(paDate(g.target))}</small>`:""}</span>${ed?`<select class="hr-in sm" data-pagoal="${p.id}|${t.id}|${g.id}" aria-label="${hrE(L4("Statut de l’objectif|Goal status|Zielstatus|حالة الهدف"))}">${paOpts(Object.entries(PA_GOAL).map(([k,l])=>[k,L4(l)]),g.status)}</select>`:""}</li>`).join("")||`<li class="hr-mut">${hrE(L4("Aucun objectif défini|No goal defined|Keine Ziele|لا أهداف"))}</li>`}</ul>${ed?`<button type="button" class="hr-btn sm" data-pathx="goal|${p.id}|${t.id}">${hri("plus",14)}${hrE(L4("Objectif|Goal|Ziel|هدف"))}</button>`:""}</section>
    <section class="wide"><h4>${hrE(L4("Mesures de suivi|Outcome measures|Verlaufsmessungen|مقاييس المتابعة"))}</h4>${t.measures!.map(m=>`<div class="pa-meas"><div><b>${hrE(m.name)}</b> <small class="hr-mut">${hrE(m.unit)} · ${hrE(m.note||"")}</small></div>${m.pts.length?paObsChart("x",m.pts.map(x=>({ts:x.d,v:x.v})),{label:m.name,unit:m.unit}):`<p class="hr-mut sm">${hrE(L4("Aucune valeur|No value yet|Noch kein Wert|لا قيم"))}</p>`}${ed?`<form class="pa-ptf" data-papoint="${p.id}|${t.id}|${m.id}"><input class="hr-in sm" type="date" value="${paToday()}" max="${paToday()}" aria-label="${hrE(L4("Date|Date|Datum|التاريخ"))}"><input class="hr-in sm num" inputmode="decimal" placeholder="${hrE(m.unit||L4("valeur|value|Wert|قيمة"))}" aria-label="${hrE(L4("Valeur|Value|Wert|القيمة"))} ${hrE(m.name)}"><button type="submit" class="hr-btn sm">${hri("plus",13)}${hrE(paW("add"))}</button></form>`:""}</div>`).join("")||`<p class="hr-mut sm">${hrE(L4("Aucune mesure définie. Les mesures sont définies par l’équipe ; aucune échelle standardisée n’est fournie.|No measure defined. Measures are defined by the team; no standardised scale is provided.|Keine Messgrößen definiert.|لا مقاييس."))}</p>`}${ed?`<button type="button" class="hr-btn sm" data-pathx="measure|${p.id}|${t.id}">${hri("plus",14)}${hrE(L4("Définir une mesure|Define a measure|Messgröße definieren|تحديد مقياس"))}</button>`:""}</section>
    <section class="wide"><h4>${hrE(L4("Notes de séance|Progress notes|Verlaufsnotizen|ملاحظات التقدم"))} <em class="hr-cnt">${t.notes!.length}</em></h4><ol class="hr-tl">${t.notes!.slice().reverse().map(n=>`<li><b>${hrE(paDate(n.d))}</b><small>${hrE(n.by)}</small><p>${hrE(n.text)}</p></li>`).join("")}</ol>${ed?`<button type="button" class="hr-btn sm" data-pathx="note|${p.id}|${t.id}">${hri("plus",14)}${hrE(L4("Note de séance|Progress note|Verlaufsnotiz|ملاحظة"))}</button>`:""}</section>
    <section class="wide"><h4>${hrE(L4("Synthèse de fin de prise en charge|Discharge summary|Abschlussbericht|ملخص نهاية الرعاية"))}</h4>${t.discharge?`<p>${hrE(t.discharge.text)}</p><small class="hr-mut">${hrE(paDate(t.discharge.d))} · ${hrE(t.discharge.by)}</small>`:ed?`<button type="button" class="hr-btn sm" data-pathx="close|${p.id}|${t.id}">${hri("check",14)}${hrE(L4("Rédiger la synthèse et clôturer|Write summary and close|Abschluss schreiben|كتابة الملخص والإغلاق"))}</button>`:`<p class="hr-mut">—</p>`}</section></div></article>`}).join("")}</div>`:paEmpty("target",L4("Aucun épisode de rééducation ou de thérapie.|No therapy episode.|Keine Therapieepisode.|لا حلقات علاج."))}`}});
