paSec("timeline",{g:"dm",clin:true,n:"Chronologie clinique|Clinical timeline|Klinische Zeitachse|التسلسل السريري",ic:"hist",html:p=>{const f=PA.ui.tl;const all=paTimeline(p).filter(x=>PA.ui.showErr||x.st!=="error");const ks=[...new Set(all.map(x=>x.k))];const sel=f.k||[];const q=paNorm(f.q);
  const list=all.filter(x=>(!sel.length||sel.includes(x.k))&&(!f.from||x.d>=f.from)&&(!f.to||x.d<=f.to)&&(!q||paNorm(x.title+" "+x.sub).includes(q)));const byM=new Map<string, PaTl[]>();list.forEach(x=>{const m=x.d.length>=7?x.d.slice(0,7):x.d.slice(0,4);if(!byM.has(m))byM.set(m,[]);byM.get(m)!.push(x)});
  return `<div class="pa-tlf"><div class="pa-chipsw">${ks.map(k=>`<button type="button" class="hr-chip sm" data-patlk="${k}" aria-pressed="${sel.includes(k)}">${hrE(L4(PA_TLK[k]))} <em>${all.filter(x=>x.k===k).length}</em></button>`).join("")}</div><div class="pa-row"><input type="search" class="hr-in sm" data-patlq value="${hrE(f.q||"")}" placeholder="${hrE(L4("Filtrer…|Filter…|Filtern…|تصفية…"))}" aria-label="${hrE(L4("Filtrer la chronologie|Filter timeline|Zeitachse filtern|تصفية التسلسل"))}"><label class="hr-mut sm">${hrE(L4("du|from|von|من"))} <input type="date" class="hr-in sm" data-patlf="from" value="${hrE(f.from||"")}"></label><label class="hr-mut sm">${hrE(L4("au|to|bis|إلى"))} <input type="date" class="hr-in sm" data-patlf="to" value="${hrE(f.to||"")}"></label>${paErrToggle()}</div></div>
   ${list.length?`<div class="pa-tlv">${[...byM.entries()].map(([m,xs])=>`<section><h4>${hrE(m.length===4?m+" — "+L4("date précise non renseignée|exact date not recorded|genaues Datum fehlt|التاريخ الدقيق غير مسجل"):new Date(m+"-15T12:00:00").toLocaleDateString(paLoc(),{month:"long",year:"numeric"}))}</h4><ol>${xs.map((x,i)=>`<li class="k-${x.k}${x.st==="error"?" pa-err":""}" style="--i:${Math.min(i,12)}"><button type="button" data-patl="${x.sec}|${x.id}"><time>${hrE(x.d.length===4?x.d:paDate(x.d,{day:"2-digit",month:"short"}))}</time><span class="pa-dot"></span><span><b>${hrE(x.title)}</b><small>${hrE(L4(PA_TLK[x.k]))}${x.sub?" · "+hrE(x.sub):""}${x.rec?" · "+hrE(L4("date d’enregistrement (date clinique non renseignée)|recorded date (clinical date not recorded)|Erfassungsdatum|تاريخ التسجيل")):""}</small></span>${hri("chev",13)}</button></li>`).join("")}</ol></section>`).join("")}</div>`:paEmpty("hist",L4("Aucun élément pour ces filtres.|No item for these filters.|Keine Einträge.|لا عناصر."))}`}});

