function paReadCE(m: HTMLElement){const d: Partial<PaEntry>={};m.querySelectorAll<HTMLInputElement>("[data-ce]").forEach(x=>{(d as unknown as Bag)[x.dataset.ce!]=x.value.trim()});if(m.querySelector<HTMLInputElement>("[data-ceprob]"))d.problems=[...m.querySelectorAll<HTMLInputElement>("[data-ceprob]:checked")].map(x=>x.dataset.ceprob!);["v","v2"].forEach(k=>{if(d[k]!==undefined&&d[k]!=="")d[k]=Number(String(d[k]).replace(",","."))});if(d.formRef==="")d.formRef=null;return d}
function paClinDlg(pid: string,kind: string,id?: string | null){const p=paGet(pid);const e=id?paEntry(p,kind,id):({} as Partial<PaEntry>);const isNew=!id;const S=PA_SEC[kind]||PA_SEC.therapy;const title=(isNew?L4(S.addN||PAW.add):L4("Modifier l’entrée|Edit entry|Eintrag bearbeiten|تعديل الإدخال"))+" — "+paName(p);
  const prov=kind==="enc"||kind==="therapy"||kind==="plans"?"":PA_PROVF(e);const reason=!isNew&&!(kind==="enc"&&e.status==="draft");
  paDialog(title,`<div class="hr-flds">${PA_FORMS[kind](e,p)}</div>${prov}${reason?paFld("ce-why","Motif de la modification (conservé dans l’historique)|Reason for change (kept in history)|Änderungsgrund|سبب التعديل",`<input id="ce-why" class="hr-in" data-cewhy>`,{req:1}):""}${kind==="enc"&&isNew?`<p class="hr-note">${hri("info",13)}${hrE(L4("La consultation est créée en brouillon ; signez-la une fois la note rédigée. Un rendez-vous du Calendrier n’est pas une consultation : le lien est facultatif.|The encounter is created as a draft; sign it once the note is written. A calendar appointment is not an encounter: the link is optional.|Konsultation als Entwurf; Termin ist keine Konsultation.|تُنشأ الاستشارة كمسودة."))}</p>`:""}`,{wide:true,icon:S.ic,okLabel:isNew?paW("add"):paW("save"),
   onOk:m=>{const d=paReadCE(m);if(kind==="obs"&&d.code!=="bp")delete d.v2;if(kind==="therapy"&&isNew){paTherapyOpen(pid,d)}else if(isNew){if(kind==="enc"){d.spec=rmPrac(d.pr)?.spec||"";}paClinAdd(pid,kind,d)}else if(kind==="enc"&&e.status==="draft"){d.spec=rmPrac(d.pr)?.spec||e.spec;paEncDraft(pid,id,d)}else{const why=m.querySelector<HTMLInputElement>("[data-cewhy]")!.value;const patch: Bag={};Object.keys(d).forEach(k=>{if(JSON.stringify(d[k])!==JSON.stringify(e[k]))patch[k]=d[k]});if(!Object.keys(patch).length)return true;paClinAmend(pid,kind,id,patch,why)}
    paSave();paRefresh();paToast(paW("saved"));return true}})}
function paHistDlg(pid: string,kind: string,id: string){const p=paGet(pid);const e=paEntry(p,kind,id);paDialog(L4("Historique des modifications|Change history|Änderungsverlauf|سجل التعديلات"),`<ol class="hr-tl">${e.amend.slice().reverse().map(a=>`<li><b>${hrE(paDT(a.at))} · ${hrE(a.by)}</b><small>${hrE(L4("Motif|Reason|Grund|السبب"))} : ${hrE(a.reason)}</small><p class="pa-prev">${Object.entries(a.prev).map(([k,v])=>`<span><i>${hrE(k)}</i> ${hrE(L4("avant|before|vorher|قبل"))} : ${hrE(v==null||v===""?"—":typeof v==="object"?JSON.stringify(v):String(v))}</span>`).join("")}</p></li>`).join("")}<li><b>${hrE(L4("Création|Created|Erstellt|إنشاء"))} · ${hrE(paDT(e.at))} · ${hrE(e.by)}</b></li></ol>`,{icon:"hist",ok:false,cancelLabel:paW("close")})}
function paEntryMenu(btn: HTMLElement,pid: string,kind: string,id: string){const p=paGet(pid);const e=paEntry(p,kind,id);const r=btn.getBoundingClientRect();const items=[];
  const editable=!(kind==="enc"&&e.status!=="draft")&&kind!=="therapy";if(editable)items.push({l:L4("Modifier (avec motif)|Edit (with reason)|Bearbeiten (mit Grund)|تعديل (مع سبب)"),ic:hri("pen",14),run:()=>paClinDlg(pid,kind,id)});
  const sts={allergies:["active","inactive","resolved"],problems:["active","resolved","inactive"],meds:["active","stopped","unknown"],plans:["active","completed"],hist:["active","inactive"]}[kind];if(sts)items.push({l:L4("Changer le statut|Change status|Status ändern|تغيير الحالة"),ic:hri("swap",14),sub:sts.filter(s=>s!==e.status).map(s=>({l:L4(PA_ESTATE[s]),run:()=>paAct(()=>paClinStatus(pid,kind,id,s),paW("saved"))}))});
  if(e.amend?.length)items.push({l:L4("Historique des modifications|Change history|Änderungsverlauf|سجل التعديلات"),ic:hri("hist",14),run:()=>paHistDlg(pid,kind,id)});
  items.push("-",{l:L4("Marquer comme saisie erronée…|Mark as entered in error…|Als Fehleintrag markieren…|تعليم كخطأ…"),ic:hri("x",14),danger:true,run:()=>paConfirm(L4("L’entrée restera visible dans l’historique, barrée, avec votre motif. Elle ne sera pas supprimée.|The entry stays visible in history, struck through, with your reason. It is not deleted.|Der Eintrag bleibt durchgestrichen sichtbar.|يبقى الإدخال مرئيًا ومشطوبًا."),why=>paAct(()=>paClinError(pid,kind,id,why),L4("Entrée marquée comme erronée|Entry marked as in error|Als Fehleintrag markiert|تم التعليم كخطأ")),{reason:true,danger:true,okLabel:L4("Marquer erronée|Mark in error|Markieren|تعليم")})});
  osMenu(Math.max(8,r.right-250),r.bottom+4,items)}
function paTherapyAct(act: string,pid: string,tid: string){const label={initial:"Évaluation initiale|Initial assessment|Erstbefund|التقييم الأولي",goal:"Nouvel objectif|New goal|Neues Ziel|هدف جديد",measure:"Définir une mesure de suivi|Define an outcome measure|Messgröße definieren|تحديد مقياس",note:"Note de séance|Progress note|Verlaufsnotiz|ملاحظة الجلسة",close:"Synthèse de fin de prise en charge|Discharge summary|Abschlussbericht|ملخص نهاية الرعاية"}[act];const forms=paForms();
  const body=act==="goal"?`<div class="hr-flds">${paFld("tg-t","Objectif (formulé avec le patient)|Goal (agreed with the patient)|Ziel|الهدف",`<input id="tg-t" class="hr-in" data-tx="text" autofocus>`,{req:1,full:1})}${paFld("tg-d","Échéance|Target date|Zieldatum|الموعد",`<input id="tg-d" type="date" class="hr-in" data-tx="target">`)}</div>`
   :act==="measure"?`<div class="hr-flds">${paFld("tm-n","Nom de la mesure|Measure name|Bezeichnung|اسم المقياس",`<input id="tm-n" class="hr-in" data-tx="name" autofocus>`,{req:1,full:1})}${paFld("tm-u","Unité|Unit|Einheit|الوحدة",`<input id="tm-u" class="hr-in" data-tx="unit">`)}${paFld("tm-f","Formulaire associé (facultatif)|Linked form (optional)|Formular (optional)|نموذج مرتبط",`<select id="tm-f" class="hr-in" data-tx="formRef">${paOpts(forms.map(f=>[f.id,f.name]),"","—")}</select>`)}${paFld("tm-o","Définition / protocole|Definition / protocol|Definition|التعريف",`<input id="tm-o" class="hr-in" data-tx="note">`,{full:1})}</div><p class="hr-mut sm">${hrE(L4("Pour un instrument standardisé, vérifiez d’abord sa licence et ses règles de cotation.|For a standardised instrument, check its licence and scoring rules first.|Lizenz und Auswertung prüfen.|تحقق من الترخيص وقواعد التنقيط."))}</p>`
   :`<textarea class="hr-in" data-tx="text" rows="6" autofocus aria-label="${hrE(L4(label))}"></textarea>${act==="close"?`<p class="hr-mut sm">${hrE(L4("La synthèse clôture l’épisode ; il restera consultable.|The summary closes the episode; it remains viewable.|Der Bericht schließt die Episode ab.|يغلق الملخص الحلقة."))}</p>`:""}`;
  paDialog(L4(label),body,{wide:act!=="goal",icon:"target",okLabel:act==="close"?L4("Clôturer l’épisode|Close episode|Episode abschließen|إغلاق الحلقة"):paW("save"),onOk:m=>{const d: Dict={};m.querySelectorAll<HTMLInputElement>("[data-tx]").forEach(x=>{(d as unknown as Bag)[x.dataset.tx!]=x.value.trim()});
   if(act==="initial")paTherapyInitial(pid,tid,d.text);if(act==="goal")paTherapyGoal(pid,tid,d);if(act==="measure")paTherapyMeasure(pid,tid,Object.assign(d,{formRef:d.formRef||null}));if(act==="note")paTherapyNote(pid,tid,d.text);if(act==="close")paTherapyClose(pid,tid,d.text);paSave();paRefresh();paToast(paW("saved"));return true}})}

