    const sum=(a as number[]).reduce((x,y)=>x+y,0);const band=(Q.bands.find(r=>sum>=r[0]&&sum<=r[1])||[0,0,""])[2];const summary=`${Q.name} : ${sum}/${Q.n*3}${band?" — "+band:""}`;
